// Package postgres implements filament.DataStore, filament.ScheduleStore and
// a pipeline store on PostgreSQL via pgx. Queries are generated by sqlc from
// datastore/postgres/queries/*.sql
package postgres

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/galaxy-io/filament"
	"github.com/galaxy-io/filament/datastore/postgres/sqlcgen"
)

// Store is a Postgres-backed filament.DataStore and filament.ScheduleStore.
type Store struct {
	pool *pgxpool.Pool
	q    *sqlcgen.Queries
}

// New wraps an already-connected pool. Run Migrate before first use.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: sqlcgen.New(pool)}
}

// Pool exposes the underlying connection pool for components backed by the
// same database, e.g. the postgres secrets provider.
func (s *Store) Pool() *pgxpool.Pool { return s.pool }

// Ping verifies database connectivity.
func (s *Store) Ping(ctx context.Context) error { return s.pool.Ping(ctx) }

// Close releases the underlying connection pool.
func (s *Store) Close() error {
	s.pool.Close()
	return nil
}

var (
	_ filament.DataStore     = (*Store)(nil)
	_ filament.ScheduleStore = (*Store)(nil)
)

// Name identifies this store implementation.
func (s *Store) Name() string { return "postgres" }

// SaveRun upserts the run row and reattaches any carried Resources into
// run_resource_states, mirroring datastore/sqlite's SaveRun contract.
func (s *Store) SaveRun(ctx context.Context, r filament.RunState) error {
	req, err := json.Marshal(r.Request)
	if err != nil {
		return fmt.Errorf("datastore/postgres: marshal request: %w", err)
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("datastore/postgres: begin: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	q := s.q.WithTx(tx)

	rows, err := q.SaveRun(ctx, sqlcgen.SaveRunParams{
		RunID:             string(r.Run),
		TenantID:          string(r.Tenant),
		PipelineID:        r.Request.PipelineID,
		PipelineVersionID: r.Request.PipelineVersionID,
		ScheduleID:        string(r.ScheduleID),
		Status:            int16(r.Status), //nolint:gosec // small enum
		Request:           req,
		Records:           r.Records,
		Bytes:             r.Bytes,
		ScheduledAt:       toTimestamptz(nullTime(r.ScheduledAt)),
		RequestedAt:       toTimestamptz(nullTime(r.RequestedAt)),
		StartedAt:         toTimestamptz(nullTime(r.StartedAt)),
		EndedAt:           toTimestamptz(r.EndedAt),
		Error:             r.Error,
		CpuSeconds:        r.CPUSeconds,
		MemoryPeakBytes:   r.MemoryPeakBytes,
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: save run: %w", err)
	}
	if rows == 0 {
		return fmt.Errorf("save run %q: %w", r.Run, filament.ErrNotFound)
	}

	for _, rs := range r.Resources {
		rs.Run = r.Run
		rs.Tenant = r.Tenant
		if err := upsertResource(ctx, q, rs); err != nil {
			return err
		}
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("datastore/postgres: commit: %w", err)
	}
	return nil
}

// TransitionRun serializes lifecycle commands on the run row and updates it
// only when the current status belongs to from.
func (s *Store) TransitionRun(
	ctx context.Context,
	tenant filament.TenantID,
	id filament.RunID,
	from []filament.RunStatus,
	to filament.RunStatus,
	opts filament.RunTransitionOptions,
) (filament.RunState, error) {
	status, err := runStatusValue(to)
	if err != nil {
		return filament.RunState{}, err
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return filament.RunState{}, fmt.Errorf("datastore/postgres: begin run transition: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	q := s.q.WithTx(tx)
	current, err := q.LockRunStatus(ctx, sqlcgen.LockRunStatusParams{TenantID: string(tenant), RunID: string(id)})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return filament.RunState{}, fmt.Errorf("transition run %q: %w", id, filament.ErrNotFound)
		}
		return filament.RunState{}, fmt.Errorf("datastore/postgres: lock run transition: %w", err)
	}
	if !slices.Contains(from, filament.RunStatus(current)) {
		return filament.RunState{}, fmt.Errorf("transition run %q from status %d: %w", id, current, filament.ErrVersionConflict)
	}
	if opts.ResetExecution {
		if err := q.ResetRunExecution(ctx, sqlcgen.ResetRunExecutionParams{
			TenantID: string(tenant), RunID: string(id), Status: status, PreserveProgress: opts.PreserveProgress,
		}); err != nil {
			return filament.RunState{}, fmt.Errorf("datastore/postgres: reset run transition: %w", err)
		}
		if err := q.ResetRunResources(ctx, sqlcgen.ResetRunResourcesParams{
			TenantID: string(tenant), RunID: string(id), Status: int16(filament.RunRequested), PreserveProgress: opts.PreserveProgress,
		}); err != nil {
			return filament.RunState{}, fmt.Errorf("datastore/postgres: reset resource transition: %w", err)
		}
	} else {
		if err := q.TransitionRun(ctx, sqlcgen.TransitionRunParams{TenantID: string(tenant), RunID: string(id), Status: status, StampEnded: opts.Ended}); err != nil {
			return filament.RunState{}, fmt.Errorf("datastore/postgres: run transition: %w", err)
		}
	}
	if err := tx.Commit(ctx); err != nil {
		return filament.RunState{}, fmt.Errorf("datastore/postgres: commit run transition: %w", err)
	}
	return s.LoadRun(ctx, tenant, id)
}

func runStatusValue(status filament.RunStatus) (int16, error) {
	if status < -1<<15 || status > 1<<15-1 {
		return 0, fmt.Errorf("datastore/postgres: run status %d is out of range", status)
	}
	return int16(status), nil //nolint:gosec // bounds checked above
}

// CreateRun inserts the run or promotes a pre-created RunScheduled row; a row
// that has progressed past RunScheduled is left untouched.
func (s *Store) CreateRun(ctx context.Context, r filament.RunState) error {
	req, err := json.Marshal(r.Request)
	if err != nil {
		return fmt.Errorf("datastore/postgres: marshal request: %w", err)
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("datastore/postgres: begin: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	q := s.q.WithTx(tx)

	rows, err := q.CreateRun(ctx, sqlcgen.CreateRunParams{
		RunID:             string(r.Run),
		TenantID:          string(r.Tenant),
		PipelineID:        r.Request.PipelineID,
		PipelineVersionID: r.Request.PipelineVersionID,
		ScheduleID:        string(r.ScheduleID),
		Status:            int16(r.Status), //nolint:gosec // small enum
		Request:           req,
		Records:           r.Records,
		Bytes:             r.Bytes,
		ScheduledAt:       toTimestamptz(nullTime(r.ScheduledAt)),
		RequestedAt:       toTimestamptz(nullTime(r.RequestedAt)),
		StartedAt:         toTimestamptz(nullTime(r.StartedAt)),
		EndedAt:           toTimestamptz(r.EndedAt),
		Error:             r.Error,
		CpuSeconds:        r.CPUSeconds,
		MemoryPeakBytes:   r.MemoryPeakBytes,
		FromStatus:        int16(filament.RunScheduled), //nolint:gosec // small enum
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: create run: %w", err)
	}
	if rows == 0 {
		return fmt.Errorf("create run %q: %w", r.Run, filament.ErrVersionConflict)
	}

	for _, rs := range r.Resources {
		rs.Run = r.Run
		rs.Tenant = r.Tenant
		if err := upsertResource(ctx, q, rs); err != nil {
			return err
		}
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("datastore/postgres: commit: %w", err)
	}
	return nil
}

// DeleteRun removes the run; resources, checkpoints, and dedup rows cascade.
// Missing is a no-op.
func (s *Store) DeleteRun(ctx context.Context, tenant filament.TenantID, id filament.RunID) error {
	if err := s.q.DeleteRun(ctx, sqlcgen.DeleteRunParams{TenantID: string(tenant), RunID: string(id)}); err != nil {
		return fmt.Errorf("datastore/postgres: delete run: %w", err)
	}
	return nil
}

// LoadRun returns the run with its current resource states reattached.
func (s *Store) LoadRun(ctx context.Context, tenant filament.TenantID, id filament.RunID) (filament.RunState, error) {
	row, err := s.q.LoadRun(ctx, sqlcgen.LoadRunParams{TenantID: string(tenant), RunID: string(id)})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return filament.RunState{}, fmt.Errorf("load run %q: %w", id, filament.ErrNotFound)
		}
		return filament.RunState{}, fmt.Errorf("datastore/postgres: load run: %w", err)
	}

	r, err := runFromRaw(row.ID, row.TenantID, row.ScheduleID, int(row.Status), row.Request,
		row.Records, row.Bytes, runTimes{
			created:   fromTimestamptz(row.CreatedAt),
			scheduled: fromTimestamptz(row.ScheduledAt),
			requested: fromTimestamptz(row.RequestedAt),
			started:   fromTimestamptz(row.StartedAt),
			ended:     fromTimestamptz(row.EndedAt),
			updated:   fromTimestamptz(row.UpdatedAt),
		}, row.Error, row.CpuSeconds, row.MemoryPeakBytes)
	if err != nil {
		return filament.RunState{}, err
	}

	resources, err := s.ListResources(ctx, tenant, id)
	if err != nil {
		return filament.RunState{}, err
	}
	r.Resources = resources
	return r, nil
}

// ListRuns returns runs matching the filter, newest effective time first, each
// with resource states attached. Effective time is StartedAt, falling back to
// RequestedAt, ScheduledAt, then CreatedAt: a pending scheduled run sorts by
// its future fire time (pinning it above finished work) and slides into
// chronological place once promoted.
func (s *Store) ListRuns(ctx context.Context, f filament.RunFilter) ([]filament.RunState, int, error) {
	q, args := listRunsQuery(f)
	rows, err := s.pool.Query(ctx, q, args...)
	if err != nil {
		return nil, 0, fmt.Errorf("datastore/postgres: list runs: %w", err)
	}
	defer rows.Close()

	var out []filament.RunState
	var ids []filament.RunID
	var total int
	for rows.Next() {
		var (
			runID, tenant, scheduleID, errMsg string
			status                            int
			req                               []byte
			records, bytes                    int64
			times                             runTimes
			cpuSeconds                        float64
			memoryPeakBytes                   int64
		)
		if err := rows.Scan(&runID, &tenant, &scheduleID, &status, &req, &records, &bytes,
			&times.created, &times.scheduled, &times.requested, &times.started, &times.ended, &times.updated,
			&errMsg, &cpuSeconds, &memoryPeakBytes, &total); err != nil {
			return nil, 0, fmt.Errorf("datastore/postgres: scan run: %w", err)
		}
		r, err := runFromRaw(runID, tenant, scheduleID, status, req, records, bytes, times, errMsg, cpuSeconds, memoryPeakBytes)
		if err != nil {
			return nil, 0, err
		}
		out = append(out, r)
		ids = append(ids, r.Run)
	}
	if err := rows.Err(); err != nil {
		return nil, 0, fmt.Errorf("datastore/postgres: list runs: %w", err)
	}

	for i, id := range ids {
		resources, err := s.ListResources(ctx, out[i].Tenant, id)
		if err != nil {
			return nil, 0, err
		}
		out[i].Resources = resources
	}
	return out, total, nil
}

func listRunsQuery(f filament.RunFilter) (string, []any) {
	q := `SELECT r.id, r.tenant_id, coalesce(r.schedule_id::text, ''), r.status, r.request, r.records, r.bytes, r.created_at, r.scheduled_at, r.requested_at, r.started_at, r.ended_at, r.updated_at, coalesce(r.error, ''), r.cpu_seconds, r.memory_peak_bytes, count(*) OVER ()
	      FROM runs r LEFT JOIN pipelines p ON p.tenant_id = r.tenant_id AND p.id = r.pipeline_id`
	args := []any{}
	arg := func(v any) string {
		args = append(args, v)
		return fmt.Sprintf("$%d", len(args))
	}
	q += " WHERE true"
	if f.Tenant != "" {
		q += " AND r.tenant_id = " + arg(string(f.Tenant))
	}
	// pipeline_id and pipeline_version_id are indexed foreign-key columns.
	if f.PipelineID != "" {
		q += " AND r.pipeline_id = " + arg(f.PipelineID)
	}
	if f.PipelineVersionID != nil {
		q += " AND r.pipeline_version_id = " + arg(*f.PipelineVersionID)
	}
	if f.Schedule != "" {
		q += " AND r.schedule_id = " + arg(string(f.Schedule))
	}
	if !f.Since.IsZero() {
		q += " AND r.started_at >= " + arg(f.Since)
	}
	if !f.Until.IsZero() {
		q += " AND r.started_at < " + arg(f.Until)
	}
	if !f.UpdatedBefore.IsZero() {
		q += " AND r.updated_at < " + arg(f.UpdatedBefore)
	}
	if len(f.Status) > 0 {
		statuses := make([]int, len(f.Status))
		for i, st := range f.Status {
			statuses[i] = int(st)
		}
		q += " AND r.status = ANY(" + arg(statuses) + ")"
	}
	if search := strings.TrimSpace(f.Search); search != "" {
		exactPlaceholder := arg(search)
		likePlaceholder := arg(escapeLikePattern(search))
		q += " AND (r.id::text = " + exactPlaceholder + " OR r.pipeline_id::text = " + exactPlaceholder +
			" OR p.name ILIKE '%' || " + likePlaceholder + " || '%' ESCAPE '\\'" +
			" OR p.description ILIKE '%' || " + likePlaceholder + " || '%' ESCAPE '\\')"
	}
	switch f.SortBy {
	case "name":
		if f.SortDescending {
			q += " ORDER BY lower(p.name) DESC NULLS LAST, r.id DESC"
		} else {
			q += " ORDER BY lower(p.name) ASC NULLS LAST, r.id ASC"
		}
	case "created_at":
		if f.SortDescending {
			q += " ORDER BY r.created_at DESC, r.id DESC"
		} else {
			q += " ORDER BY r.created_at ASC, r.id ASC"
		}
	case "updated_at":
		if f.SortDescending {
			q += " ORDER BY r.updated_at DESC, r.id DESC"
		} else {
			q += " ORDER BY r.updated_at ASC, r.id ASC"
		}
	default:
		if f.SortDescending {
			q += " ORDER BY COALESCE(r.started_at, r.requested_at, r.scheduled_at, r.created_at) DESC, r.id DESC"
		} else {
			q += " ORDER BY COALESCE(r.started_at, r.requested_at, r.scheduled_at, r.created_at) ASC, r.id ASC"
		}
	}
	if f.Limit > 0 {
		q += " LIMIT " + arg(f.Limit)
	}
	if f.Offset > 0 {
		q += " OFFSET " + arg(f.Offset)
	}
	return q, args
}

// escapeLikePattern makes user input literal when placed between the wildcards
// used by list search. PostgreSQL otherwise treats %, _, and \ as pattern syntax.
func escapeLikePattern(value string) string {
	return strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(value)
}

// runTimes groups a run row's lifecycle stamps so they travel as a named set
// rather than six adjacent *time.Time positionals.
type runTimes struct {
	created   *time.Time
	scheduled *time.Time
	requested *time.Time
	started   *time.Time
	ended     *time.Time
	updated   *time.Time
}

func runFromRaw(runID, tenant, scheduleID string, status int, req []byte, records, bytes int64, times runTimes, errMsg string, cpuSeconds float64, memoryPeakBytes int64) (filament.RunState, error) {
	var r filament.RunState
	r.Run = filament.RunID(runID)
	r.Tenant = filament.TenantID(tenant)
	r.ScheduleID = filament.ScheduleID(scheduleID)
	r.Status = filament.RunStatus(status)
	r.Records = records
	r.Bytes = bytes
	r.Error = errMsg
	r.CPUSeconds = cpuSeconds
	r.MemoryPeakBytes = memoryPeakBytes
	r.CreatedAt = derefTime(times.created)
	r.ScheduledAt = derefTime(times.scheduled)
	r.RequestedAt = derefTime(times.requested)
	r.StartedAt = derefTime(times.started)
	r.UpdatedAt = derefTime(times.updated)
	r.EndedAt = times.ended
	if err := json.Unmarshal(req, &r.Request); err != nil {
		return filament.RunState{}, fmt.Errorf("datastore/postgres: unmarshal request: %w", err)
	}
	return r, nil
}

func derefTime(t *time.Time) time.Time {
	if t == nil {
		return time.Time{}
	}
	return *t
}

func nullTime(t time.Time) *time.Time {
	if t.IsZero() {
		return nil
	}
	return &t
}

func toTimestamptz(t *time.Time) pgtype.Timestamptz {
	if t == nil {
		return pgtype.Timestamptz{Valid: false}
	}
	return pgtype.Timestamptz{Time: *t, Valid: true}
}

func fromTimestamptz(t pgtype.Timestamptz) *time.Time {
	if !t.Valid {
		return nil
	}
	tt := t.Time
	return &tt
}

// UpsertResource inserts or updates one resource state row.
func (s *Store) UpsertResource(ctx context.Context, rs filament.ResourceState) error {
	return upsertResource(ctx, s.q, rs)
}

func upsertResource(ctx context.Context, q *sqlcgen.Queries, rs filament.ResourceState) error {
	rows, err := q.UpsertResource(ctx, sqlcgen.UpsertResourceParams{
		RunID:        string(rs.Run),
		ResourceName: rs.Resource,
		TenantID:     string(rs.Tenant),
		Status:       int16(rs.Status), //nolint:gosec // small enum
		Records:      rs.Records,
		Bytes:        rs.Bytes,
		Error:        rs.Error,
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: upsert resource: %w", err)
	}
	if rows == 0 {
		return fmt.Errorf("upsert resource for run %q: %w", rs.Run, filament.ErrNotFound)
	}
	return nil
}

// ListResources returns a run's resource states.
func (s *Store) ListResources(ctx context.Context, tenant filament.TenantID, id filament.RunID) ([]filament.ResourceState, error) {
	rows, err := s.q.ListResources(ctx, sqlcgen.ListResourcesParams{TenantID: string(tenant), RunID: string(id)})
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: list resources: %w", err)
	}
	out := make([]filament.ResourceState, len(rows))
	for i, row := range rows {
		out[i] = filament.ResourceState{
			Run:      filament.RunID(row.RunID),
			Resource: row.ResourceName,
			Tenant:   filament.TenantID(row.TenantID),
			Enabled:  true,
			Status:   filament.RunStatus(row.Status),
			Records:  row.Records,
			Bytes:    row.Bytes,
			Error:    row.Error,
		}
	}
	return out, nil
}

// SaveCheckpoint upserts a resource's cursor for the run.
func (s *Store) SaveCheckpoint(ctx context.Context, tenant filament.TenantID, id filament.RunID, cp filament.Checkpoint) error {
	cursor, err := json.Marshal(cp.Raw())
	if err != nil {
		return fmt.Errorf("datastore/postgres: marshal checkpoint: %w", err)
	}
	rows, err := s.q.SaveCheckpoint(ctx, sqlcgen.SaveCheckpointParams{
		TenantID:     string(tenant),
		RunID:        string(id),
		ResourceName: cp.Resource(),
		Cursor:       cursor,
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: save checkpoint: %w", err)
	}
	if rows == 0 {
		return fmt.Errorf("save checkpoint for run %q: %w", id, filament.ErrNotFound)
	}
	return nil
}

// LoadCheckpoint returns a resource's saved cursor for the run.
func (s *Store) LoadCheckpoint(ctx context.Context, tenant filament.TenantID, id filament.RunID, resource string) (filament.Checkpoint, error) {
	cursor, err := s.q.LoadCheckpoint(ctx, sqlcgen.LoadCheckpointParams{TenantID: string(tenant), RunID: string(id), ResourceName: resource})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, fmt.Errorf("load checkpoint %q/%q: %w", id, resource, filament.ErrNotFound)
		}
		return nil, fmt.Errorf("datastore/postgres: load checkpoint: %w", err)
	}
	var raw map[string]any
	if err := json.Unmarshal(cursor, &raw); err != nil {
		return nil, fmt.Errorf("datastore/postgres: unmarshal checkpoint: %w", err)
	}
	return &filament.CheckpointData{ResourceName: resource, Cursor: raw}, nil
}

// SaveResourceCheckpoint upserts durable cross-run progress for one immutable
// pipeline route and resource.
func (s *Store) SaveResourceCheckpoint(ctx context.Context, tenant filament.TenantID, state filament.ResourceCheckpointState) error {
	if state.Checkpoint == nil || state.Checkpoint.Resource() != state.Key.Resource {
		return fmt.Errorf("datastore/postgres: save resource checkpoint: resource mismatch")
	}
	cursor, err := json.Marshal(state.Checkpoint.Raw())
	if err != nil {
		return fmt.Errorf("datastore/postgres: marshal resource checkpoint: %w", err)
	}
	rows, err := s.q.SaveResourceCheckpoint(ctx, sqlcgen.SaveResourceCheckpointParams{
		TenantID:   string(tenant),
		PipelineID: state.Key.PipelineID, PipelineVersionID: state.Key.PipelineVersionID,
		RouteKey: state.Key.Route, ResourceName: state.Key.Resource,
		Cursor: cursor, LastRunID: string(state.Run),
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: save resource checkpoint: %w", err)
	}
	if rows == 0 {
		return fmt.Errorf("save resource checkpoint for pipeline %q: %w", state.Key.PipelineID, filament.ErrNotFound)
	}
	return nil
}

// LoadResourceCheckpoint returns durable cross-run progress for one route and
// resource.
func (s *Store) LoadResourceCheckpoint(ctx context.Context, tenant filament.TenantID, key filament.ResourceCheckpointKey) (filament.ResourceCheckpointState, error) {
	row, err := s.q.LoadResourceCheckpoint(ctx, sqlcgen.LoadResourceCheckpointParams{
		TenantID:   string(tenant),
		PipelineID: key.PipelineID, PipelineVersionID: key.PipelineVersionID,
		RouteKey: key.Route, ResourceName: key.Resource,
	})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return filament.ResourceCheckpointState{}, fmt.Errorf("load resource checkpoint %q/%q: %w", key.Route, key.Resource, filament.ErrNotFound)
		}
		return filament.ResourceCheckpointState{}, fmt.Errorf("datastore/postgres: load resource checkpoint: %w", err)
	}
	var raw map[string]any
	if err := json.Unmarshal(row.Cursor, &raw); err != nil {
		return filament.ResourceCheckpointState{}, fmt.Errorf("datastore/postgres: unmarshal resource checkpoint: %w", err)
	}
	return filament.ResourceCheckpointState{
		Key: key, Run: filament.RunID(row.LastRunID), UpdatedAt: row.UpdatedAt.Time,
		Checkpoint: &filament.CheckpointData{ResourceName: key.Resource, Cursor: raw},
	}, nil
}

// ListResourceCheckpoints returns every durable cursor under one route,
// ordered by resource.
func (s *Store) ListResourceCheckpoints(ctx context.Context, tenant filament.TenantID, route filament.ResourceCheckpointRoute) ([]filament.ResourceCheckpointState, error) {
	rows, err := s.q.ListResourceCheckpoints(ctx, sqlcgen.ListResourceCheckpointsParams{
		TenantID:   string(tenant),
		PipelineID: route.PipelineID, PipelineVersionID: route.PipelineVersionID, RouteKey: route.Route,
	})
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: list resource checkpoints: %w", err)
	}
	states := make([]filament.ResourceCheckpointState, 0, len(rows))
	for _, row := range rows {
		var raw map[string]any
		if err := json.Unmarshal(row.Cursor, &raw); err != nil {
			return nil, fmt.Errorf("datastore/postgres: unmarshal resource checkpoint: %w", err)
		}
		key := filament.ResourceCheckpointKey{
			PipelineID: route.PipelineID, PipelineVersionID: route.PipelineVersionID,
			Route: route.Route, Resource: row.ResourceName,
		}
		states = append(states, filament.ResourceCheckpointState{
			Key: key, Run: filament.RunID(row.LastRunID), UpdatedAt: row.UpdatedAt.Time,
			Checkpoint: &filament.CheckpointData{ResourceName: row.ResourceName, Cursor: raw},
		})
	}
	return states, nil
}

// DeleteResourceCheckpoint resets durable progress for one route/resource.
func (s *Store) DeleteResourceCheckpoint(ctx context.Context, tenant filament.TenantID, key filament.ResourceCheckpointKey) error {
	err := s.q.DeleteResourceCheckpoint(ctx, sqlcgen.DeleteResourceCheckpointParams{
		TenantID:   string(tenant),
		PipelineID: key.PipelineID, PipelineVersionID: key.PipelineVersionID,
		RouteKey: key.Route, ResourceName: key.Resource,
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: delete resource checkpoint: %w", err)
	}
	return nil
}

// DedupSeen reports whether seq has already been applied for (tenant, run),
// advancing the run's high-water mark on the first call to see it. This
// relies on the tracker processing each run's facts through
// one sequential pump, so seq only ever increases per run
func (s *Store) DedupSeen(ctx context.Context, tenant string, run filament.RunID, seq uint64) (bool, error) {
	_, err := s.q.AdvanceDedupSeen(ctx, sqlcgen.AdvanceDedupSeenParams{
		TenantID: tenant,
		RunID:    string(run),
		Seq:      int64(seq), //nolint:gosec // per-run batch counter, never near int64 max
	})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return true, nil
		}
		return false, fmt.Errorf("datastore/postgres: dedup seen: %w", err)
	}
	return false, nil
}

// SaveSchedule upserts the schedule row, releasing any ClaimDue lease.
func (s *Store) SaveSchedule(ctx context.Context, st filament.ScheduleState) error {
	return saveSchedule(ctx, s.q, st)
}

func saveSchedule(ctx context.Context, q *sqlcgen.Queries, st filament.ScheduleState) error {
	rows, err := q.SaveSchedule(ctx, sqlcgen.SaveScheduleParams{
		ScheduleID:    string(st.ID),
		TenantID:      string(st.Spec.Tenant),
		PipelineID:    st.Spec.PipelineID,
		Name:          toText(st.Spec.Name),
		CronExpr:      st.Spec.Cron,
		Timezone:      st.Spec.Timezone,
		OverlapPolicy: int16(st.Spec.Overlap), //nolint:gosec // small enum
		Enabled:       st.Enabled,
		LastFiredAt:   toTimestamptz(st.LastFired),
		NextFireAt:    toTimestamptz(st.NextFire),
		CreatedAt:     toTimestamptz(nullTime(st.CreatedAt)),
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: save schedule: %w", err)
	}
	if rows == 0 {
		return fmt.Errorf("datastore/postgres: save schedule %q: pipeline %q: %w", st.ID, st.Spec.PipelineID, filament.ErrNotFound)
	}
	return nil
}

// LoadSchedule returns one schedule by id.
func (s *Store) LoadSchedule(ctx context.Context, tenant filament.TenantID, id filament.ScheduleID) (filament.ScheduleState, error) {
	row, err := s.q.LoadSchedule(ctx, sqlcgen.LoadScheduleParams{TenantID: string(tenant), ScheduleID: string(id)})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return filament.ScheduleState{}, fmt.Errorf("load schedule %q: %w", id, filament.ErrNotFound)
		}
		return filament.ScheduleState{}, fmt.Errorf("datastore/postgres: load schedule: %w", err)
	}
	return scheduleFromLoadRow(row.ID, row.TenantID, row.PipelineID, row.Name, row.CronExpr, row.Timezone,
		row.OverlapPolicy, row.Enabled, row.LastFiredAt, row.NextFireAt, row.CreatedAt)
}

// LoadPipelineSchedule returns the schedule attached to pipelineID.
func (s *Store) LoadPipelineSchedule(ctx context.Context, tenant filament.TenantID, pipelineID string) (filament.ScheduleState, error) {
	row, err := s.q.LoadPipelineSchedule(ctx, sqlcgen.LoadPipelineScheduleParams{TenantID: string(tenant), PipelineID: pipelineID})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return filament.ScheduleState{}, fmt.Errorf("load pipeline schedule %q: %w", pipelineID, filament.ErrNotFound)
		}
		return filament.ScheduleState{}, fmt.Errorf("datastore/postgres: load pipeline schedule: %w", err)
	}
	return scheduleFromLoadRow(row.ID, row.TenantID, row.PipelineID, row.Name, row.CronExpr, row.Timezone,
		row.OverlapPolicy, row.Enabled, row.LastFiredAt, row.NextFireAt, row.CreatedAt)
}

// ListSchedules returns schedules matching the filter.
func (s *Store) ListSchedules(ctx context.Context, f filament.ScheduleFilter) ([]filament.ScheduleState, error) {
	var filterEnabled pgtype.Bool
	if f.Enabled != nil {
		filterEnabled = pgtype.Bool{Bool: *f.Enabled, Valid: true}
	}
	rows, err := s.q.ListSchedules(ctx, sqlcgen.ListSchedulesParams{
		TenantID:      string(f.Tenant),
		FilterEnabled: filterEnabled,
		Lim:           int32(f.Limit), //nolint:gosec // caller-provided small limit
	})
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: list schedules: %w", err)
	}
	out := make([]filament.ScheduleState, len(rows))
	for i, row := range rows {
		st, err := scheduleFromLoadRow(row.ID, row.TenantID, row.PipelineID, row.Name, row.CronExpr, row.Timezone,
			row.OverlapPolicy, row.Enabled, row.LastFiredAt, row.NextFireAt, row.CreatedAt)
		if err != nil {
			return nil, err
		}
		out[i] = st
	}
	return out, nil
}

// DeleteSchedule removes a schedule by id along with its pre-created scheduled
// runs, so nothing lingers as upcoming work. The runs reap goes first: deleting
// the schedules row SET-NULLs runs.schedule_id, after which the rows are
// unreachable by schedule id even inside this transaction.
func (s *Store) DeleteSchedule(ctx context.Context, tenant filament.TenantID, id filament.ScheduleID) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("datastore/postgres: begin schedule delete: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	q := s.q.WithTx(tx)
	if err := q.DeleteScheduleScheduledRuns(ctx, sqlcgen.DeleteScheduleScheduledRunsParams{
		TenantID:   string(tenant),
		ScheduleID: toText(string(id)),
		Status:     int16(filament.RunScheduled), //nolint:gosec // small enum
	}); err != nil {
		return fmt.Errorf("datastore/postgres: delete schedule scheduled runs: %w", err)
	}
	if err := q.DeleteSchedule(ctx, sqlcgen.DeleteScheduleParams{TenantID: string(tenant), ScheduleID: string(id)}); err != nil {
		return fmt.Errorf("datastore/postgres: delete schedule: %w", err)
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("datastore/postgres: commit schedule delete: %w", err)
	}
	return nil
}

// ClaimDue leases up to limit, enabled schedules not
// currently under an unexpired lease, and stamps them claimed_at = now() in
// the same transaction as the SELECT ... FOR UPDATE SKIP LOCKED so a second
// scheduler replica racing this call cannot pick up the same row: it will
// either block-and-skip (SKIP LOCKED) or see claimed_at within
// filament.ScheduleLeaseTTL and filter it out. The lease is released by the
// next SaveSchedule call or expires after the TTL if the scheduler that
// claimed it crashes before calling SaveSchedule.
func (s *Store) ClaimDue(ctx context.Context, now time.Time, limit int) ([]filament.ScheduleState, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: begin: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	q := s.q.WithTx(tx)

	rows, err := q.ClaimDue(ctx, sqlcgen.ClaimDueParams{
		Now:         pgtype.Timestamptz{Time: now, Valid: true},
		LeaseCutoff: pgtype.Timestamptz{Time: now.Add(-filament.ScheduleLeaseTTL), Valid: true},
		Lim:         int32(limit), //nolint:gosec // caller-provided small limit
	})
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: claim due: %w", err)
	}

	out := make([]filament.ScheduleState, len(rows))
	ids := make([]string, len(rows))
	for i, row := range rows {
		st, err := scheduleFromLoadRow(row.ID, row.TenantID, row.PipelineID, row.Name, row.CronExpr, row.Timezone,
			row.OverlapPolicy, row.Enabled, row.LastFiredAt, row.NextFireAt, row.CreatedAt)
		if err != nil {
			return nil, err
		}
		out[i] = st
		ids[i] = row.ID
	}

	if len(ids) > 0 {
		err := q.LeaseSchedules(ctx, sqlcgen.LeaseSchedulesParams{
			ClaimedAt:   pgtype.Timestamptz{Time: now, Valid: true},
			ScheduleIds: ids,
		})
		if err != nil {
			return nil, fmt.Errorf("datastore/postgres: lease claimed schedules: %w", err)
		}
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("datastore/postgres: commit claim: %w", err)
	}
	return out, nil
}

// ReleaseScheduleClaim makes a claimed occurrence eligible for retry.
func (s *Store) ReleaseScheduleClaim(ctx context.Context, tenant filament.TenantID, id filament.ScheduleID) error {
	err := s.q.ReleaseScheduleClaim(ctx, sqlcgen.ReleaseScheduleClaimParams{TenantID: string(tenant), ScheduleID: string(id)})
	if err != nil {
		return fmt.Errorf("datastore/postgres: release schedule claim: %w", err)
	}
	return nil
}

func toText(s string) pgtype.Text {
	if s == "" {
		return pgtype.Text{}
	}
	return pgtype.Text{String: s, Valid: true}
}

func scheduleFromLoadRow(id, tenant, pipelineID string, name pgtype.Text, cronExpr, tz string,
	overlap int16, enabled bool, lastFired, nextFire, createdAt pgtype.Timestamptz,
) (filament.ScheduleState, error) {
	var created time.Time
	if createdAt.Valid {
		created = createdAt.Time
	}
	return filament.ScheduleState{
		ID: filament.ScheduleID(id),
		Spec: filament.ScheduleSpec{
			Tenant:     filament.TenantID(tenant),
			Name:       name.String,
			PipelineID: pipelineID,
			Cron:       cronExpr,
			Timezone:   tz,
			Overlap:    filament.OverlapPolicy(overlap),
			Enabled:    enabled,
		},
		Enabled:   enabled,
		LastFired: fromTimestamptz(lastFired),
		NextFire:  fromTimestamptz(nextFire),
		CreatedAt: created,
	}, nil
}
